"""Self-contained interactive report; scenario sliders never submit trades."""
import json


def render(result, forecasts, daily):
    visible = []
    for area in ('DK1', 'DK2'):
        for horizon in (1, 6, 24):
            visible += [r for r in forecasts if r['area'] == area and r['horizon_hours'] == horizon][-168:]
    payload = json.dumps({'result': result, 'forecasts': visible, 'daily': daily}, allow_nan=False).replace('<', '\\u003c')
    return TEMPLATE.replace('__DATA__', payload)


TEMPLATE = '''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>WindRisk | Forecast & imbalance laboratory</title>
<style>
:root{--ink:#173329;--muted:#64756b;--green:#176e4d;--orange:#ca682f;--line:#dce5dc}*{box-sizing:border-box}body{margin:0;background:#f4f6f0;color:var(--ink);font:15px/1.6 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:36px 26px}header{border-top:5px solid var(--green);padding:24px 0 14px}.eyebrow{font-size:12px;font-weight:750;letter-spacing:2px;color:var(--green)}h1{font-size:48px;line-height:1.1;letter-spacing:-2px;margin:15px 0}h2{font-size:21px;margin:0 0 10px}p{margin:8px 0}.muted,small{color:var(--muted)}.tag{display:inline-block;border:1px solid var(--line);padding:4px 10px;border-radius:20px;font-size:12px;margin:4px 4px 0 0}.controls{display:flex;flex-wrap:wrap;gap:18px;align-items:end;background:#e8eee3;padding:18px;border-radius:12px;margin:22px 0}label{display:block;font-size:12px;font-weight:650}select{font:inherit;background:white;border:1px solid #bccaba;border-radius:7px;padding:9px 35px 9px 10px;color:var(--ink)}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.card,section{background:white;border:1px solid var(--line);border-radius:12px;padding:23px}.card strong{font-size:31px;display:block;line-height:1.4}.card span{font-size:12px;color:var(--muted)}section{margin-top:20px}.head{display:flex;justify-content:space-between;align-items:center;gap:10px}.head span{font-size:12px;color:var(--muted)}svg{display:block;width:100%;height:auto;margin:14px 0}.legend{font-size:12px}.legend b{margin-right:18px}.chart-note{font-size:12px;color:var(--muted)}.risk-controls{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;background:#f5f7f2;border-radius:8px;padding:16px;margin:18px 0}input{width:100%;accent-color:var(--green)}output{display:block;font-size:19px;color:var(--green)}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:11px 8px;text-align:left;border-bottom:1px solid var(--line);white-space:nowrap}th{font-weight:600;color:var(--muted)}td:first-child{font-weight:650}.note{border-left:3px solid var(--orange);padding:9px 14px;margin:18px 0;background:#fcf7ed;font-size:13px}.positive{color:#176e4d}.negative{color:#ae3c2f}a{color:var(--green)}footer{font-size:12px;color:var(--muted);padding:24px 0}pre{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere}details{margin-top:15px}@media(max-width:700px){main{padding:20px 14px}h1{font-size:36px}.cards{grid-template-columns:1fr}.risk-controls{grid-template-columns:1fr}.head{display:block}.card strong{font-size:28px}}
</style></head><body><main>
<header><div class="eyebrow">WINDRISK / ENERGY RESEARCH</div><h1>Forecast the wind.<br>Understand the exposure.</h1><p class="muted">DK1 + DK2 · Short-term generation forecasts and imbalance scenarios</p><span class="tag">Historical research</span><span class="tag" id="period"></span><span class="tag">No live orders</span></header>
<div class="controls"><div><label for="area">Price area</label><select id="area"><option>DK1</option><option>DK2</option></select></div><div><label for="horizon">Forecast lead time</label><select id="horizon"><option value="1">1 hour</option><option value="6" selected>6 hours</option><option value="24">24 hours</option></select></div><p class="muted" id="selected"></p></div>
<div class="cards"><article class="card"><small>Forecast error · zone generation</small><strong id="mae"></strong><span>Mean absolute error in MWh per delivery hour</span></article><article class="card"><small>Change vs persistence</small><strong id="skill"></strong><span>Positive means lower test error</span></article><article class="card"><small>Observed 90% interval coverage</small><strong id="coverage"></strong><span>Measured on unseen hours; target is 90%</span></article></div>
<section><div class="head"><h2>Generation / latest seven test days</h2><span>Aggregate zone energy · MWh per hour</span></div><p class="legend"><b style="color:#176e4d">Actual generation</b><b style="color:#ca682f">Selected forecast</b><b style="color:#7d9987">90% calibration interval</b></p><div id="chart"></div><p class="chart-note" id="chartRange"></p><p class="note" id="coverageNote"></p></section>
<section><div class="head"><h2>Nomination & imbalance laboratory</h2><span>Change assumptions to explore exposure</span></div><p class="muted">Scale a hypothetical share of zone wind generation. Q10 nominates a lower volume, Q50 the median, and Q90 a higher volume. Each is an alternative scenario for the same delivery hours.</p>
<div class="risk-controls"><div><label for="share">Share of zone production</label><input id="share" type="range" min="0.1" max="5" step="0.1" value="1"><output id="shareValue" for="share"></output></div><div><label for="shortfall">Stress charge for shortfall · €/MWh</label><input id="shortfall" type="range" min="0" max="500" step="5" value="100"><output id="shortfallValue" for="shortfall"></output></div><div><label for="surplus">Stress charge for surplus · €/MWh</label><input id="surplus" type="range" min="0" max="500" step="5" value="25"><output id="surplusValue" for="surplus"></output></div></div>
<div class="table-wrap"><table><thead><tr><th>Nomination</th><th>Shortfall MWh</th><th>Surplus MWh</th><th>Historical effect €</th><th>Daily tail loss €</th><th>Stress cost €</th></tr></thead><tbody id="policies"></tbody></table></div><p class="chart-note">Historical effect = (actual − nominated) × (imbalance price − day-ahead price). Positive is a benefit relative to selling actual output at day-ahead prices. Daily tail loss is the mean of the worst 5% of complete-day losses, rounded up to whole days.</p><div id="riskChart"></div><p class="chart-note">Cumulative historical imbalance effect in EUR: Q10 green · Q50 orange · Q90 blue. Missing priced hours are excluded; partial days remain in this plot.</p>
<p class="note">These are counterfactual nomination scenarios, not executable day-ahead bids. Lead times are relative to delivery, not auction deadlines. Hourly generation is assumed flat within each hour. Stress charges are hypothetical penalties, separate from historical settlement prices; they do not alter the historical-effect column.</p></section>
<section><h2>Model comparison & audit</h2><div class="table-wrap"><table><thead><tr><th>Area / lead</th><th>Selected before test</th><th>Selected MAE</th><th>Ridge MAE</th><th>Persistence MAE</th><th>Coverage</th></tr></thead><tbody id="models"></tbody></table></div><p id="quality" class="muted"></p><details><summary>Method, source provenance and split dates</summary><pre id="audit"></pre></details></section>
<footer>Source: <a href="https://www.energidataservice.dk/tso-electricity/GenerationProdTypeExchange">Energinet generation</a>, <a href="https://www.energidataservice.dk/tso-electricity/ImbalancePrice">imbalance prices</a> and <a href="https://www.energidataservice.dk/tso-electricity/DayAheadPrices">day-ahead prices</a>. Generation archives contain revisions and are not a point-in-time feed. Reporting delay is assumed. No weather inputs, actual plant model, fees, taxes, curtailment or market-access constraints. Results are not production trading recommendations.</footer>
</main><script id="payload" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('payload').textContent), result=data.result;
const el=id=>document.getElementById(id), fmt=(n,d=1)=>Number(n).toLocaleString('en-GB',{minimumFractionDigits:d,maximumFractionDigits:d});
function plot(series,colors,labels,band){
 const w=1040,h=280,left=65,right=15,top=14,bottom=34,all=series.flat().concat(band?band.flat():[]);if(!all.length)return '<p>No observations.</p>';
 let lo=Math.min(0,...all),hi=Math.max(...all),span=Math.max(hi-lo,1),n=series[0].length;
 const x=i=>left+i*(w-left-right)/Math.max(1,n-1),y=v=>top+(hi-v)*(h-top-bottom)/span;
 let s=`<svg role="img" aria-label="Time series with dates and values" viewBox="0 0 ${w} ${h}">`;
 for(let i=0;i<4;i++){let v=lo+span*i/3;s+=`<path d="M${left} ${y(v)} H${w-right}" stroke="#e3e9e1"/><text x="0" y="${y(v)+4}" font-size="12" fill="#64756b">${fmt(v,0)}</text>`;}
 if(band){const points=band[1].map((v,i)=>`${x(i)},${y(v)}`).concat(band[0].map((v,i)=>`${x(i)},${y(v)}`).reverse()).join(' ');s+=`<polygon points="${points}" fill="#dce9de" opacity="0.8"/>`;}
 series.forEach((arr,k)=>{s+=`<polyline fill="none" stroke="${colors[k]}" stroke-width="2" points="${arr.map((v,i)=>`${x(i)},${y(v)}`).join(' ')}"/>`;});
 [0,Math.floor((n-1)/2),n-1].forEach((i,k)=>{s+=`<text x="${x(i)}" y="${h-7}" text-anchor="${k===0?'start':k===2?'end':'middle'}" font-size="12" fill="#64756b">${labels[i]||''}</text>`;});return s+'</svg>';
}
function update(){
 const area=el('area').value,h=Number(el('horizon').value),m=result.metrics[`${area}_${h}`];
 el('selected').textContent=`Selected model: ${m.model} · ${m.forecast_count} evaluated hours`;
 el('mae').textContent=fmt(m.mae_mwh);el('skill').textContent=fmt(100*(1-m.mae_mwh/m.persistence_mae_mwh))+'%';el('coverage').textContent=fmt(m.coverage90*100)+'%';
 const rows=data.forecasts.filter(r=>r.area===area&&r.horizon_hours===h);
 el('chart').innerHTML=plot([rows.map(r=>r.actual_mwh),rows.map(r=>r.forecast_mwh)],['#176e4d','#ca682f'],rows.map(r=>r.target_utc.slice(5,16).replace('T',' ')),[rows.map(r=>r.lower90_mwh),rows.map(r=>r.upper90_mwh)]);
 el('chartRange').textContent=`${rows[0].target_utc.slice(0,16)} → ${rows.at(-1).target_utc.slice(0,16)} UTC. Latest input is ${h+2} hours before the target.`;
 el('coverageNote').textContent=m.coverage90<.9?`Observed coverage is below 90% for this slice. Treat the uncertainty band as imperfect; historical coverage does not guarantee future coverage.`:`Observed coverage meets the 90% target in this slice. This does not guarantee future coverage or simultaneous coverage across hours.`;
 const share=Number(el('share').value)/100,scale=share/result.share,short=Number(el('shortfall').value),surplus=Number(el('surplus').value);
 el('shareValue').textContent=fmt(share*100)+'%';el('shortfallValue').textContent='€'+fmt(short,0);el('surplusValue').textContent='€'+fmt(surplus,0);
 el('policies').innerHTML=['q10','q50','q90'].map(p=>{let r=m.policies[p],effect=r.imbalance_effect_eur*scale;return `<tr><td>${p.toUpperCase()}</td><td>${fmt(r.shortfall_mwh*scale)}</td><td>${fmt(r.surplus_mwh*scale)}</td><td class="${effect>=0?'positive':'negative'}">${fmt(effect,0)}</td><td>${r.daily_loss?fmt(r.daily_loss.historical_tail_mean95_eur*scale,0):'N/A'}</td><td>${fmt(scale*(r.shortfall_mwh*short+r.surplus_mwh*surplus),0)}</td></tr>`;}).join('');
 const lines=['q10','q50','q90'].map(p=>{let total=0;return data.daily.filter(r=>r.area===area&&r.horizon_hours===h&&r.policy===p).map(r=>total+=r.effect_eur*scale)}),days=data.daily.filter(r=>r.area===area&&r.horizon_hours===h&&r.policy==='q10').map(r=>r.day.slice(5));
 el('riskChart').innerHTML=plot(lines,['#176e4d','#ca682f','#5579a8'],days);
 el('audit').textContent=JSON.stringify({selected:result.model_audit[`${area}_${h}`],availability:result.availability_assumption,settlement:result.settlement_assumption,quality:result.data_quality,skipped:result.skipped,provenance:result.provenance},null,2);
}
el('period').textContent=result.test_start_utc.slice(0,10)+' → '+result.test_end_exclusive_utc.slice(0,10)+' (end exclusive)';
el('models').innerHTML=Object.values(result.metrics).map(m=>`<tr><td>${m.area} / ${m.horizon_hours}h</td><td>${m.model}</td><td>${fmt(m.mae_mwh)}</td><td>${fmt(m.ridge_mae_mwh)}</td><td>${fmt(m.persistence_mae_mwh)}</td><td>${fmt(100*m.coverage90)}%</td></tr>`).join('');
el('quality').textContent='Forecast metrics use all valid forecast hours. Settlement requires all four quarter-hour prices; missing prices are excluded and counted in the audit. Daily tail losses use complete 24-hour UTC days only.';
['area','horizon','share','shortfall','surplus'].forEach(id=>el(id).addEventListener('input',update));update();
</script></body></html>'''
